/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const dir = mkdtempSync(join(process.cwd(), '.catalog-acceptance-'));
const path = join(dir, 'catalog.json');
const seed = [
  { id: 'z', title: 'Ёлка 🌲', pinned: false },
  { id: 'legacy', title: 'Старая карточка' },
  { id: 'a', title: 'Закреплённая', pinned: true },
  { id: 'm', title: 'Обычная', pinned: false },
];
const normalized = seed.map(card => ({ ...card, pinned: card.pinned ?? false }));
const importCode = \"import { loadCatalog, setPinned, saveCatalog } from './catalog/src/catalog.mjs'; const [path, id, value] = process.argv.slice(1);\";
function session(code, ...args) {
  const result = spawnSync(process.execPath, ['--input-type=module', '-e', importCode + code, path, ...args], { encoding: 'utf8' });
  assert.equal(result.status, 0, result.stderr);
  return result.stdout.trim();
}
function load() {
  return JSON.parse(session('console.log(JSON.stringify(loadCatalog(path)));'));
}
function saved() {
  return JSON.parse(readFileSync(path, 'utf8'));
}

try {
  writeFileSync(path, JSON.stringify(seed));
  assert.deepEqual(load(), normalized);
  console.log('R1/R6 legacy field reads as false; initial records match');

  for (const [id, pinned] of [['z', true], ['a', false], ['legacy', true]]) {
    const expected = normalized.map(card => card.id === id ? { ...card, pinned } : card);
    writeFileSync(path, JSON.stringify(seed));
    session('saveCatalog(path, setPinned(loadCatalog(path), id, value === \"true\"));', id, String(pinned));
    assert.deepEqual(saved(), expected);
    assert.deepEqual(load(), expected);
    console.log("'`R1–R4 disk and separate-process reload: ${id} -> ${pinned}; all records and order match`);
  }

  const original = readFileSync(path, '"'utf8');
  const failure = spawnSync(process.execPath, ['--input-type=module', '-e', importCode + 'saveCatalog(path, setPinned(loadCatalog(path), id, true));', path, 'missing'], { encoding: 'utf8' });
  assert.equal(failure.status, 1);
  assert.match(failure.stderr, /Error: Unknown card: missing/);
  assert.equal(readFileSync(path, 'utf8'), original);
  console.log('R5 unknown id: error, exit 1, file bytes identical');

  const duplicates = [
    { id: 'same', title: 'First', pinned: false },
    { id: 'other', title: 'Middle', pinned: false },
    { id: 'same', title: 'Last', pinned: false },
  ];
  writeFileSync(path, JSON.stringify(duplicates));
  session('saveCatalog(path, setPinned(loadCatalog(path), id, true));', 'same');
  const changed = load().filter((card, i) => card.pinned "'!== duplicates[i].pinned);
  console.log('"'Repeated id changed records:', JSON.stringify(changed));
} finally {
  rmSync(dir, { recursive: true });
}
NODE"

